import{_ as s,o as e,c as i,a4 as n}from"./chunks/framework.BUqnS5H7.js";const f=JSON.parse('{"title":"Buffer Pool","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/02-innodb-internals/chapter-02-buffer-pool.md","filePath":"mysql/02-innodb-internals/chapter-02-buffer-pool.md"}'),l={name:"mysql/02-innodb-internals/chapter-02-buffer-pool.md"};function t(r,a,o,d,p,c){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="buffer-pool" tabindex="-1" data-src-line="1" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">Buffer Pool <a class="header-anchor" href="#buffer-pool" aria-label="Permalink to &quot;Buffer Pool&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><p data-src-line="3" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">一条 <code>SELECT</code> 的快慢，很大程度取决于它要的数据页在不在内存里。在内存，是纳秒级的事；不在，就要等一次磁盘随机读。InnoDB 用 Buffer Pool 把「最可能被再访问」的数据页留在内存，而「怎么判断哪些页该留、哪些页该淘汰」这件事，是它比操作系统页面缓存做得更精细的地方。</p></blockquote><h2 id="_1-为什么需要-buffer-pool" tabindex="-1" data-src-line="5" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">1. 为什么需要 Buffer Pool <a class="header-anchor" href="#_1-为什么需要-buffer-pool" aria-label="Permalink to &quot;1. 为什么需要 Buffer Pool&quot;">​</a></h2><h3 id="_1-1-从一次随机读的代价说起" tabindex="-1" data-src-line="7" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">1.1 从一次随机读的代价说起 <a class="header-anchor" href="#_1-1-从一次随机读的代价说起" aria-label="Permalink to &quot;1.1 从一次随机读的代价说起&quot;">​</a></h3><p data-src-line="9" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">数据库查询的性能瓶颈，绝大多数时候不是 CPU，而是磁盘 IO。一次内存访问约 100 纳秒，而一次机械硬盘的随机读约 10 毫秒，SSD 也要约 0.1 毫秒——<strong>差了四到六个数量级</strong>。</p><p data-src-line="11" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">这意味着：一条 SQL 要读的数据页如果已经在内存里，几乎不花时间；如果每次都要从磁盘读，再快的索引也快不起来。Buffer Pool 存在的全部意义，就是把「反复要读的页」钉在内存里，让绝大多数读操作命中内存，而不是磁盘。</p><h3 id="_1-2-buffer-pool-的读写单位-16kb-页" tabindex="-1" data-src-line="13" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">1.2 Buffer Pool 的读写单位：16KB 页 <a class="header-anchor" href="#_1-2-buffer-pool-的读写单位-16kb-页" aria-label="Permalink to &quot;1.2 Buffer Pool 的读写单位：16KB 页&quot;">​</a></h3><p data-src-line="15" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">InnoDB 不按「行」而是按「页」读写磁盘。默认页大小 <code>innodb_page_size = 16KB</code>，聚簇索引的数据页和二级索引的索引页，都以这个单位被整体读入 Buffer Pool。</p><p data-src-line="17" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">这样做的原因是磁盘的顺序读远快于随机读：一次读 16KB 和一次读 1 行，磁盘寻道时间差不多，但前者一次能装下几百行。页越大，单次 IO 的「有效载荷」越高。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_page_size&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 默认 16384（16KB）</span></span></code></pre></div><p data-src-line="23" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">页的内部布局（File Header、Page Directory、User Records 等）在 <a href="./chapter-01-data-page.html">数据页</a> 展开，这里只需记住：<strong>Buffer Pool 是一块内存，里面装的全是 16KB 的页。</strong></p><h2 id="_2-内存组织与淘汰策略" tabindex="-1" data-src-line="25" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">2. 内存组织与淘汰策略 <a class="header-anchor" href="#_2-内存组织与淘汰策略" aria-label="Permalink to &quot;2. 内存组织与淘汰策略&quot;">​</a></h2><h3 id="_2-1-buffer-pool-内部的三张链表" tabindex="-1" data-src-line="27" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">2.1 Buffer Pool 内部的三张链表 <a class="header-anchor" href="#_2-1-buffer-pool-内部的三张链表" aria-label="Permalink to &quot;2.1 Buffer Pool 内部的三张链表&quot;">​</a></h3><p data-src-line="29" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">Buffer Pool 不是一块无序的内存。InnoDB 用三张链表管理其中的页：</p><table tabindex="0"><thead data-src-line="31" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><tr data-src-line="31" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><th style="text-align:left;">链表</th><th style="text-align:left;">作用</th></tr></thead><tbody data-src-line="33" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><tr data-src-line="33" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><td style="text-align:left;"><strong>Free List</strong></td><td style="text-align:left;">空闲页链表。刚启动时全挂这里，用完一个取一个</td></tr><tr data-src-line="34" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><td style="text-align:left;"><strong>LRU List</strong></td><td style="text-align:left;">所有已缓存页，按「最近访问时间」排序。淘汰就从这里选</td></tr><tr data-src-line="35" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><td style="text-align:left;"><strong>Flush List</strong></td><td style="text-align:left;">脏页链表。被修改过但还没写回磁盘的页，按修改时间排序</td></tr></tbody></table><p data-src-line="37" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">三张链表解决三个不同的问题：Free List 回答「去哪找空页」，LRU List 回答「内存满了淘汰谁」，Flush List 回答「哪些脏页该刷盘」。其中最难、也最值得讲透的是 LRU List 的淘汰策略。</p><h3 id="_2-2-为什么不能直接用-lru" tabindex="-1" data-src-line="39" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">2.2 为什么不能直接用 LRU <a class="header-anchor" href="#_2-2-为什么不能直接用-lru" aria-label="Permalink to &quot;2.2 为什么不能直接用 LRU&quot;">​</a></h3><p data-src-line="41" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">朴素的 LRU 是：最近访问的页放链表头部，内存满了就淘汰尾部的页。这个策略在大多数场景够用，但有两个 InnoDB 特有的场景会把它打垮。</p><p data-src-line="43" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>场景一：预读污染。</strong> InnoDB 发现你在顺序扫描时，会「预读」——把当前页后面的若干页也一起读进来，赌你接着会访问它们。如果赌错了，这些预读进来的页根本没人访问，却挤占了 LRU 头部，把真正的热数据顶到尾部。</p><p data-src-line="45" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>场景二：全表扫描污染。</strong> 一条 <code>SELECT * FROM big_table</code> 会把整张表几十万页依次读进内存。这些页每页只被访问一次，如果每次都进 LRU 头部，扫完一张表，Buffer Pool 里装的就全是「以后再也不会访问」的垃圾页，之前缓存的热数据全被挤掉。</p><p data-src-line="47" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">两个场景的本质相同：<strong>「只访问一次的页」混进了「会反复访问的页」，把 LRU 的头部污染了。</strong> InnoDB 的对策，是把 LRU 链表从一段改成两段。</p><h3 id="_2-3-分区-lru-young-区与-old-区" tabindex="-1" data-src-line="49" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">2.3 分区 LRU：young 区与 old 区 <a class="header-anchor" href="#_2-3-分区-lru-young-区与-old-区" aria-label="Permalink to &quot;2.3 分区 LRU：young 区与 old 区&quot;">​</a></h3><p data-src-line="51" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">InnoDB 的 LRU 链表被切成两段：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│  young 区（约 5/8）  热数据，反复被访问      │  ← 链表头部</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│  old 区（约 3/8）    新读入的页、冷数据      │  ← 链表尾部</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre></div><p data-src-line="61" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">核心规则有两条：</p><ol data-src-line="63" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><li data-src-line="63" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>新读入的页放在 old 区头部，而不是 young 区头部。</strong></li><li data-src-line="64" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>页在 old 区停留超过 <code>innodb_old_blocks_time</code>（默认 1000ms）后，再次被访问才晋升到 young 区头部。</strong></li></ol><p data-src-line="66" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">为什么这两条能挡住污染？把全表扫描代入：扫描读进来的页全部落在 old 区头部，它们在被读一次之后，很可能在 1 秒内就被后续读进来的页推到 old 区尾部，最终被淘汰。<strong>因为它们从没在 old 区停留超过 1 秒，所以永远没有资格晋升 young 区</strong>，young 区里的热数据分毫未动。</p><p data-src-line="68" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">反过来，一个真正热门的页（比如频繁按主键查询的那一页），第一次读进 old 区后，1 秒之后又被访问，就晋升到 young 区，从此被 LRU 正常保护。</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">innodb_old_blocks_pct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  = 37     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># old 区占比（37% ≈ 3/8）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">innodb_old_blocks_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1000   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># old 区停留阈值，单位毫秒</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">两个参数怎么调</p><ul data-src-line="76" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><li data-src-line="76" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><code>innodb_old_blocks_pct</code> 调大，old 区变大，抗全表扫描污染的能力更强，但热数据能占的空间变小。默认 37 对大多数 OLTP 是合理的。</li><li data-src-line="77" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">如果业务有定期的批量扫描（报表、备份），可以临时把 <code>innodb_old_blocks_time</code> 调大（如 5000），让扫描进来的页更难晋升，进一步保护热数据；扫描结束再调回。</li></ul></div><h2 id="_3-容量评估与配置运维" tabindex="-1" data-src-line="80" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">3. 容量评估与配置运维 <a class="header-anchor" href="#_3-容量评估与配置运维" aria-label="Permalink to &quot;3. 容量评估与配置运维&quot;">​</a></h2><h3 id="_3-1-命中率-buffer-pool-健康度的唯一指标" tabindex="-1" data-src-line="82" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">3.1 命中率：Buffer Pool 健康度的唯一指标 <a class="header-anchor" href="#_3-1-命中率-buffer-pool-健康度的唯一指标" aria-label="Permalink to &quot;3.1 命中率：Buffer Pool 健康度的唯一指标&quot;">​</a></h3><p data-src-line="84" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">判断 Buffer Pool 够不够大，不看它占了多少内存，看命中率。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GLOBAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> STATUS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Innodb_buffer_pool_read%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p data-src-line="90" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">两个关键值：</p><ul data-src-line="92" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><li data-src-line="92" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><code>Innodb_buffer_pool_read_requests</code>：逻辑读次数，即「读页」的总请求数；</li><li data-src-line="93" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><code>Innodb_buffer_pool_reads</code>：物理读次数，即「内存没有、真正从磁盘读」的次数。</li></ul><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命中率 = 1 - reads / read_requests</span></span></code></pre></div><p data-src-line="99" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">生产环境这个值应稳定在 99% 以上。低于 99%，说明 Buffer Pool 太小，频繁发生物理读，该加大 <code>innodb_buffer_pool_size</code>。</p><h3 id="_3-2-参数与实例拆分" tabindex="-1" data-src-line="101" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">3.2 参数与实例拆分 <a class="header-anchor" href="#_3-2-参数与实例拆分" aria-label="Permalink to &quot;3.2 参数与实例拆分&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">innodb_buffer_pool_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     = 4G   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 建议物理内存的 50%~70%</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">innodb_buffer_pool_instances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 8   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 多实例减少锁竞争</span></span></code></pre></div><p data-src-line="108" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">两个点值得展开：</p><p data-src-line="110" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>大小。</strong> Buffer Pool 不是越大越好。超过物理内存会导致操作系统换页，反而更慢；留出内存给连接线程、排序缓冲区、操作系统本身。经验值是物理内存的 50%~70%，但前提是命中率达标——命中率已经 99.9%，再加内存也没有收益。</p><p data-src-line="112" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>实例拆分。</strong> Buffer Pool 只有一个实例时，所有线程读写它都要抢一把全局锁，高并发下这把锁成为瓶颈。<code>innodb_buffer_pool_instances</code> 把 Buffer Pool 切成多个独立实例，各自维护自己的 LRU/Free/Flush 链表，锁竞争被分摊。经验规则：Buffer Pool 小于 8GB 时一个实例即可，大于 8GB 时按 CPU 核数拆分。</p><h3 id="_3-3-预热-重启后的性能爬坡" tabindex="-1" data-src-line="114" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">3.3 预热：重启后的性能爬坡 <a class="header-anchor" href="#_3-3-预热-重启后的性能爬坡" aria-label="Permalink to &quot;3.3 预热：重启后的性能爬坡&quot;">​</a></h3><p data-src-line="116" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">Buffer Pool 在内存里，数据库一重启就全空了。重启后的一段时间，命中率从 0 开始爬升，大量查询被迫物理读，表现为「刚重启完特别慢」。</p><p data-src-line="118" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">InnoDB 的解决办法是把「哪些页是热点」记下来：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 关机时把热页列表 dump 到磁盘，启动时按列表加载回来</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_buffer_pool_dump_at_shutdown&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 默认 ON</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_buffer_pool_load_at_startup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 默认 ON</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_buffer_pool_dump_pct&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 默认 25，只 dump 最热的 25% 页</span></span></code></pre></div><p data-src-line="127" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">默认只记录最热的 25% 页，是因为全量 dump 会让大内存实例的启动时间过长。可以在「启动快」和「预热全」之间权衡：内存大、业务高峰临近重启，可以临时调高 <code>innodb_buffer_pool_dump_pct</code> 到 50~75。</p><h2 id="_4-读写加速机制" tabindex="-1" data-src-line="129" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">4. 读写加速机制 <a class="header-anchor" href="#_4-读写加速机制" aria-label="Permalink to &quot;4. 读写加速机制&quot;">​</a></h2><h3 id="_4-1-change-buffer-写操作的第二处缓冲" tabindex="-1" data-src-line="131" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">4.1 Change Buffer：写操作的第二处缓冲 <a class="header-anchor" href="#_4-1-change-buffer-写操作的第二处缓冲" aria-label="Permalink to &quot;4.1 Change Buffer：写操作的第二处缓冲&quot;">​</a></h3><p data-src-line="133" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">Buffer Pool 解决「读」的缓存问题，Change Buffer 解决「写」的一部分。</p><p data-src-line="135" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">修改一行数据时，除了改聚簇索引，还要同步维护这条记录上的<strong>二级索引</strong>。如果某个二级索引页恰好不在内存里，朴素的做法是把它从磁盘读进来再改。Change Buffer 提供了另一条路：<strong>先不读，把「对那个索引页的修改」记录在 Change Buffer 里，等这个索引页之后真的被读进内存时，再把攒下的修改一次性合并（merge）上去。</strong></p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>朴素做法：写 → 读二级索引页 → 改 → 刷盘</span></span>
<span class="line"><span>Change Buffer：写 → 记录修改 → 索引页之后被读时再 merge</span></span></code></pre></div><p data-src-line="142" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">省下的是一次「为了写而读」的磁盘 IO。对写多读少、二级索引多的表，收益显著。</p><p data-src-line="144" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>为什么只对非唯一二级索引生效？</strong></p><ul data-src-line="146" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><li data-src-line="146" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">聚簇索引不行：行数据本身就存在聚簇索引页上，改了行必然要动聚簇索引页，没有「延迟合并」的空间；</li><li data-src-line="147" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">唯一索引不行：插入新值时必须立即读索引页校验「唯一性」是否被违反，没法延迟。</li></ul><p data-src-line="149" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">所以 Change Buffer 只服务「非唯一二级索引」。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_change_buffer%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- innodb_change_buffer_max_size：Change Buffer 占 Buffer Pool 的最大比例，默认 25</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- innodb_change_buffering：缓存哪些操作，默认 all（inserts/deletes/purges/changes 都缓存）</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">什么时候该调</p><p data-src-line="158" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">写密集、二级索引多的场景（日志表、流水表），可以把 <code>innodb_change_buffer_max_size</code> 提到 40~50。但 Change Buffer 本质上是用内存换「延后合并」，如果表读也很频繁，merge 会被迫频繁发生，收益下降——所以读多写少的场景保持默认即可。</p></div><h3 id="_4-2-自适应哈希索引-ahi" tabindex="-1" data-src-line="161" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">4.2 自适应哈希索引（AHI） <a class="header-anchor" href="#_4-2-自适应哈希索引-ahi" aria-label="Permalink to &quot;4.2 自适应哈希索引（AHI）&quot;">​</a></h3><p data-src-line="163" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">B+ 树的等值查询要沿着树从根走到叶子，路径上有多次比较。如果某个索引页被频繁地做等值查询，InnoDB 会「记住」这个模式，为它额外建一张内存哈希表，后续同样的等值查询直接用哈希定位，从「走树」的 O(log N) 降到「查哈希」的 O(1)。</p><p data-src-line="165" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">这个「自动监控、自动建、自动用」的过程，就是 Adaptive Hash Index 的「自适应」含义。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_adaptive_hash_index%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- innodb_adaptive_hash_index：是否启用，默认 ON</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- innodb_adaptive_hash_index_parts：哈希分区数，默认 8</span></span></code></pre></div><p data-src-line="173" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">AHI 只对<strong>等值查询</strong>有效，范围查询（<code>&gt;</code>, <code>BETWEEN</code>）无法用哈希，仍走 B+ 树。它的代价是：哈希表本身要占内存，且维护哈希表需要额外加锁。在高并发写入场景下，AHI 的锁竞争可能成为新的瓶颈，此时应当关闭：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> GLOBAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> innodb_adaptive_hash_index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> OFF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="_5-最佳实践" tabindex="-1" data-src-line="179" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md">5. 最佳实践 <a class="header-anchor" href="#_5-最佳实践" aria-label="Permalink to &quot;5. 最佳实践&quot;">​</a></h2><ol data-src-line="181" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><li data-src-line="181" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>先看命中率，再定大小</strong>：<code>Innodb_buffer_pool_reads / read_requests</code> 决定要不要加内存，而不是拍脑袋。</li><li data-src-line="182" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>命中率 99% 是底线</strong>：低于它先查是不是有大查询、全表扫描在污染，而不是盲目加内存。</li><li data-src-line="183" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>Buffer Pool 占物理内存 50%~70%</strong>：留出内存给连接、排序和操作系统。</li><li data-src-line="184" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>大于 8GB 就拆实例</strong>：按 CPU 核数设置 <code>innodb_buffer_pool_instances</code>。</li><li data-src-line="185" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>写多读少、二级索引多，才调大 Change Buffer</strong>；读多写少保持默认。</li><li data-src-line="186" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>高并发写入且 AHI 锁竞争明显时，关闭 AHI</strong>。</li><li data-src-line="187" data-src-file="mysql/02-innodb-internals/chapter-02-buffer-pool.md"><strong>生产环境务必开启 dump/load 预热</strong>，避免重启后长时间低命中率。</li></ol>`,67)])])}const b=s(l,[["render",t]]);export{f as __pageData,b as default};
